WITH Ranked AS (SELECT seller_id, item_id, ROW_NUMBER() OVER (PARTITION BY seller_id ORDER BY order_date ASC) AS rn FROM Orders) SELECT u.user_id AS seller_id, CASE WHEN i.item_brand = u.favorite_brand THEN 'yes' ELSE 'no' END AS 2nd_item_fav_brand FROM Users u LEFT JOIN Ranked r ON u.user_id = r.seller_id AND r.rn = 2 LEFT JOIN Items i ON r.item_id = i.item_id;
